export default {
  channel: 'add-product',
  replyChannel: 'add-product-reply',
  events: {
    addProductFromMLP: {
      name: 'add-product-from-mlp',
      replies: {
        success: 'add-product-from-mlp-success',
        successFromByWeightDialog:
          'add-product-from-mlp-success-from-byWeight-dialog',
        successFromReturnProductDialog:
          'add-product-from-mlp-success-from-return-product-dialog',
        error: 'add-product-from-mlp-error',
        errorFromByWeightDialog:
          'add-product-from-mlp-error-from-byWeight-dialog',
        errorFromReturnProductDialog:
          'add-product-from-mlp-error-from-return-product-dialog',
      },
    },
    addProductsFromMLP: {
      name: 'add-products-from-mlp',
      replies: {
        success: 'add-products-from-mlp-success',
        error: 'add-products-from-mlp-error',
      },
    },
    addNewProduct: {
      name: 'add-new-product',
      replies: {
        success: 'add-new-product-success',
        error: 'add-new-product-error',
      },
    },
  },
}
