<template>
  <VTextField
    ref="input"
    v-currency="options"
    :readonly="config.readonly"
    :label="config.label"
    :filled="config.filled"
    :rounded="config.rounded"
    :value="formattedValue"
    :class="config.class"
    :color="config.color"
    :suffix="config.suffix"
    :background-color="config.backgroundColor"
    :disabled="config.disabled ? config.disabled : false"
    :error-messages="config.errorMessage(config.fieldName)"
    :prepend-inner-icon="config.prependIcon ? config.prependIcon : null"
    @change="onChange"
    @input="onInput"
    @focus="onFocus"
    @blur="onBlur"
    @keydown.enter="onEnter"
  />
</template>

<script>
export default {
  name: 'MoneyTextField',
  props: {
    value: {
      type: Number,
      default: null,
    },
    options: {
      type: Object,
      default: () => {},
    },
    config: {
      type: Object,
      default: () => {},
    },
  },
  data() {
    return {
      formattedValue: null,
    }
  },
  methods: {
    setValue(value) {
      this.$ci.setValue(this.$refs.input, value)
    },
    onInput(value) {
      if (!this.$refs.input) return
      this.$emit('input', this.$ci.getValue(this.$refs.input))
      this.formattedValue = value
    },
    onChange(value) {
      this.$emit('change', this.$ci.getValue(this.$refs.input))
      this.formattedValue = value
    },
    onFocus($event) {
      this.$emit('focus', $event)
    },
    onBlur() {
      this.$emit('blur')
    },
    onEnter() {
      this.$emit('enter')
    },
  },
  watch: {
    value(value) {
      this.setValue(value)
    },
  },
  mounted() {
    this.setValue(this.value)
    this.$emit('moneyTextField-is-mounted')
  },
}
</script>
