import { required, maxLength } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.dialog.isOpen,
    icon: 'mdi-view-grid-plus',
    title: state.hasSimilarProducts
      ? 'productsView.addProductDialog.title.notFound'
      : 'productsView.addProductDialog.title.create',
    titleBackground: '',
    titleColor: 'textPrimary',
    buttons: {
      cancel: true,
      accept: !state.hasSimilarProducts,
    },
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    persistent: true,
    height: state.hasSimilarProducts
      ? 630
      : state.currentView === 'Sales'
      ? 600
      : 530,
    maxWidth: 500,
    acceptButtonText: 'shared.send',
    isAcceptButtonDisabled: state.dialog.isAcceptButtonDisabled,
    onClickCancel: () => {
      methods.dialog.track({
        type: 'interaction',
        action: 'click',
        category: state.dialog.routeName,
        screen: 'AddNewProductDialog',
        name: `Cancel`,
      })
      methods.dialog.closeDialog()
    },
    onClickAccept: () => {
      if (state.hasSimilarProducts) {
        methods.dialog.createProduct()
        return
      }
      methods.dialog.acceptDialog()
    },
    id: 'add-product-form',
  },
  fields: [
    {
      id: 'name',
      type: 'input',
      valueType: 'string',
      label: 'productsView.addProductDialog.fields.name',
      errorMessage: 'productsView.addProductDialog.errorMessage.name',
      color: 'primaryColor',
      visible: true,
      autofocus: true,
      validators: { required, maxLength: maxLength(100) },
    },
    {
      id: 'alternativeName',
      type: 'input',
      valueType: 'string',
      label: 'productsView.addProductDialog.fields.alternativeName',
      errorMessage: 'productsView.addProductDialog.errorMessage.altName',
      color: 'primaryColor',
      required: true,
      visible: true,
      validators: { required, maxLength: maxLength(100) },
    },
    {
      id: 'price',
      type: 'input',
      valueType: 'string',
      label: 'productsView.addProductDialog.fields.price',
      errorMessage: 'productsView.addProductDialog.errorMessage.price',
      color: 'primaryColor',
      required: true,
      visible: true,
      validators: { required, minValue: value => value > 0 },
    },
    {
      id: 'isGramaje',
      type: 'radio',
      label: 'productsView.addProductDialog.fields.isGramaje.label',
      color: 'productPrimary',
      show: state.showByWeight,
      options: [
        {
          label: 'productsView.addProductDialog.fields.isGramaje.options.units',
          value: 0,
        },
        {
          label:
            'productsView.addProductDialog.fields.isGramaje.options.isGramaje',
          value: 1,
        },
      ],
      defaultValue: 0,
      visible: true,
      validators: {},
    },
    {
      id: 'amount',
      type: 'input',
      valueType: 'string',
      label:
        state.inputs.isGramaje === 1
          ? 'salesView.ticket.grams'
          : 'productsView.addProductDialog.fields.amount',
      errorMessage: 'productsView.addProductDialog.errorMessage.amount',
      color: 'primaryColor',
      defaultValue: 1,
      required:
        state.currentView === 'Sales' && state.inputs.isGramaje === 1
          ? true
          : false,
      visible: state.currentView === 'Sales',
      validators:
        state.currentView === 'Sales'
          ? { required, minValue: value => value > 0 }
          : { minValue: value => value > 0 },
    },
  ],
  id: 'add-product-form',
})

export default setConfig
