<template>
  <div>
    <span class="d-flex align-center mt-n2 mb-2">
      <span class="barcode-scanned font-weight-medium">
        <v-icon class="mr-1">mdi-barcode-scan</v-icon>
        {{ $barcodeScanner.getPreviousCode() }}
      </span>
      <span class="text-caption ml-2">{{
        validCodeText($barcodeScanner.getPreviousCode())
      }}</span>
    </span>
    <p class="text-body-1">
      {{ getTranslatedText('productsView.addProductDialog.matchInfo') }} <br />
      {{ getTranslatedText('productsView.addProductDialog.matchSelect') }}
    </p>
    <ScrollContainer height="340px" max-height="340px" class="mt-4">
      <div
        v-for="product in similarProducts"
        :key="
          `${
            product.fromMlp
              ? `similarProduct-mlp-${product.id}`
              : `similarProduct-slp-${product.id}`
          } similarProduct-${product.id}`
        "
      >
        <v-tooltip bottom>
          <template v-slot:activator="{ on }">
            <v-card
              class="mb-2 similar-product"
              flat
              v-on="on"
              @click="clickProduct(product)"
              v-track:click="{
                category: $route.name,
                screen: 'SimilarProductsAlert',
                name: product.fromMlp
                  ? 'Add similar product'
                  : 'Select similar product',
              }"
            >
              <v-card-text class="pa-4">
                <div class="d-flex justify-space-between">
                  <div class="d-flex flex-column">
                    <p class="text-h6 mb-0">
                      {{ product.name }} {{ product.alternativeName }}
                    </p>
                    <div
                      class="d-flex justify-space-between align-start text-body-1 grey--text"
                    >
                      <div class="d-flex flex-column">
                        <div class="d-flex align-center">
                          <v-icon class="mr-1" color="grey">
                            {{
                              isSupportedUpcOrEan(product.upc)
                                ? 'mdi-barcode'
                                : 'mdi-barcode-off'
                            }}
                          </v-icon>

                          {{ product.upc }}
                        </div>
                        <span class="text-caption">
                          {{ validCodeText(product.upc) }}
                        </span>
                      </div>
                      <div
                        v-if="!product.fromMlp"
                        class="d-flex align-center mx-4"
                      >
                        <v-icon class="mr-1" color="grey"
                          >mdi-basket-fill</v-icon
                        >
                        {{ product.quantity }}
                      </div>
                      <div v-if="!product.fromMlp" class="d-flex align-center">
                        <v-icon class="mr-1" color="grey"
                          >$currencyUsdCircle</v-icon
                        >
                        {{ formatNumberFromDbToCurrency(product.price) }}
                      </div>
                      <div v-else class="d-flex align-center">
                        <v-icon class="mr-1" color="grey">mdi-new-box</v-icon>
                        {{
                          getTranslatedText('productsView.addProductDialog.add')
                        }}
                      </div>
                    </div>
                  </div>
                </div>
              </v-card-text>
            </v-card>
          </template>
          <span>
            {{
              product.fromMlp
                ? getTranslatedText('productsView.addProductDialog.productAdd')
                : getTranslatedText(
                    'productsView.addProductDialog.productSelect'
                  )
            }}
          </span>
        </v-tooltip>
      </div>
      <v-card
        class="mb-2 similar-product"
        flat
        @click="$emit('update:hasSimilarProducts', false)"
        v-track:click="{
          category: $route.name,
          screen: 'SimilarProductsAlert',
          name: 'Create new product',
        }"
      >
        <v-card-text class="pa-4 d-flex justify-center align-center">
          <p class="text-h6 mb-0">
            {{
              getTranslatedText('productsView.addProductDialog.createProduct')
            }}
          </p>
        </v-card-text>
      </v-card>
    </ScrollContainer>
  </div>
</template>

<script>
import { mapState } from 'vuex'

import MLP_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'

import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'
import upcTools from '@/tools/upc'
import { getNow } from '@/tools/dates'

import rendererEventsService from '@/services/renderer/rendererEvents'

import ScrollContainer from '@/components/shared/ScrollContainer'

export default {
  name: 'SimilarProductsAlert',
  components: { ScrollContainer },
  props: {
    hasSimilarProducts: {
      type: Boolean,
      required: true,
    },
    fromReturnProductDialog: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      similarProducts: [],
    }
  },
  computed: {
    ...mapState('products', { products: state => state.data.products }),
  },
  methods: {
    isSupportedUpcOrEan: upcTools.isSupportedUpcOrEan,
    getTranslatedText,
    formatNumberFromDbToCurrency,
    validCodeText(upc) {
      return `(${
        upcTools.isSupportedUpcOrEan(upc)
          ? this.getTranslatedText('productsView.similarProducts.validCode')
          : this.getTranslatedText('productsView.similarProducts.invalidCode')
      })`
    },
    setSimilarProductsFromSlp() {
      const regex = upcTools.getRegex(this.$barcodeScanner.getPreviousCode())
      this.similarProducts = this.products.filter(product => {
        return upcTools.availableProduct(product) && regex.test(product.upc)
      })
    },
    setSimilarProductsFromMlp() {
      rendererEventsService.send(MLP_API_EVENTS.channel, {
        event: MLP_API_EVENTS.events.findSimilarUpc.name,
        data: {
          upc: this.$barcodeScanner.getPreviousCode(),
          upcsToExclude: this.similarProducts.map(prod => prod.upc),
        },
      })
    },
    clickProduct(product) {
      if (!product.fromMlp) {
        this.selectProduct(product)
        return
      }
      this.addProduct(product)
    },
    selectProduct(product) {
      this.$root.$emit(
        'productAddedFromMatch',
        product.upc,
        this.fromReturnProductDialog
      )
      this.$emit('close')
    },
    addProduct(product) {
      rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
        event: ADD_PRODUCT_EVENTS.events.addProductFromMLP.name,
        data: {
          item: { property: 'upc_code', value: product.upc, limit: 1 },
          fromReturnProductDialog: this.fromReturnProductDialog,
        },
      })
      this.$emit('close')
    },
    similarUpcMlpResponseListener(event, payload) {
      const replies = {
        [MLP_API_EVENTS.events.findSimilarUpc.replies.success]: () => {
          this.similarProducts.push(
            ...payload.data.products.map(prod => ({
              id: prod._id,
              name: prod.prod_name,
              alternativeName: prod.prod_alt_name,
              upc: prod.upc_code,
              quantity: 0,
              price: prod.prod_price,
              fromMlp: true,
            }))
          )
          this.updateHasSimilarProducts()
        },
        [MLP_API_EVENTS.events.findSimilarUpc.replies.error]: () => {
          this.updateHasSimilarProducts()
        },
      }
      if (payload.event in replies) replies[payload.event]()
      this.$loading.hide()
    },
    updateHasSimilarProducts() {
      this.$track({
        type: 'system',
        action: 'product_match',
        category: this.$route.name,
        screen: 'SimilarProductsAlert',
        name: 'Finish search similar products',
        extra_data: {
          label1: 'timestamp',
          value1: getNow(),
        },
      })
      if (this.similarProducts.length === 0) {
        this.$emit('update:hasSimilarProducts', false)
        return
      }
      this.$track({
        type: 'system',
        action: 'product_match',
        category: this.$route.name,
        screen: 'SimilarProductsAlert',
        name: 'Show similar products alert',
      })
    },
  },
  beforeMount() {
    rendererEventsService.subscribe(
      MLP_API_EVENTS.replyChannel,
      this.similarUpcMlpResponseListener
    )
  },
  mounted() {
    this.$track({
      type: 'system',
      action: 'product_match',
      category: this.$route.name,
      screen: 'SimilarProductsAlert',
      name: 'Start search similar products',
      extra_data: {
        label1: 'timestamp',
        value1: getNow(),
      },
    })
    this.$loading.show('searchProduct')
    this.setSimilarProductsFromSlp()
    this.setSimilarProductsFromMlp()
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      MLP_API_EVENTS.replyChannel,
      this.similarUpcMlpResponseListener
    )
  },
}
</script>

<style scoped lang="scss">
.barcode-scanned {
  background: var(--v-cardBackgroundSecondary-base);
  padding: 4px 12px;
  border-radius: 10px;
  line-height: 35px;
}

.similar-product {
  background: var(--v-cardBackgroundSecondary-base);
  &:hover {
    background: var(--v-productCardAvailablePrimary-lighten4);
  }
}
</style>
