<template>
  <v-tooltip right color="accent">
    <template v-slot:activator="{ on, attrs }">
      <div v-bind="attrs" v-on="on" :style="{ height: `${iconSize.y}px` }">
        <img
          :src="getCategoryURL(categoryName)"
          :height="iconSize.y"
          :width="iconSize.x"
        />
      </div>
    </template>
    <span>
      {{ getTranslatedText(`superCategories.${categoryName}`) }}
    </span>
  </v-tooltip>
</template>

<script>
import { getTranslatedText } from '@/tools/data'

export default {
  name: 'CategoryIcon',
  props: {
    categoryName: {
      type: String,
      default: 'other',
    },
    iconSize: {
      type: Object,
      default: () => ({ x: 45, y: 45 }),
    },
  },
  methods: {
    getTranslatedText,
    getCategoryURL: function(name) {
      return require(`@/assets/superCategories/${name}.svg`)
    },
  },
}
</script>

<style lang="scss"></style>
