<template>
  <Dialog :config="dialogConfig.dialogData">
    <SimilarProductsAlert
      v-if="hasSimilarProducts"
      :has-similar-products.sync="hasSimilarProducts"
      :from-return-product-dialog="fromReturnProductDialog"
      @close="onCloseDialog"
    />
    <div v-else>
      <span class="barcode-scanned font-weight-medium text-body-1">
        <v-icon class="mr-1">mdi-barcode-scan</v-icon>
        {{ $barcodeScanner.getPreviousCode() }}
      </span>
      <br />
      <span class="text-caption ml-3">{{ validCodeText }}</span>
      <Form :config="dialogConfig" class="mt-6" />
    </div>
  </Dialog>
</template>

<script>
import { mapState, mapActions } from 'vuex'
import { isNil } from 'ramda'

import { testMode } from '@/config/env'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'

import {
  cleanObjectObserver,
  getObjectCopy,
  getTranslatedText,
} from '@/tools/data'
import { formatNumberToDb } from '@/tools/numbersFormat'
import { getViewStore } from '@/tools/view'
import upcTools from '@/tools/upc'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import productsActions from '@/store/products/actions.types'
import productsViewActions from '@/store/productsView/action.types'
import salesViewActions from '@/store/salesView/actions.types'
import purchasesViewActions from '@/store/purchasesView/actions.types'
import customPromotionsViewActions from '@/store/customPromotionsView/actions.types'

import Dialog from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'
import setConfig from '@/components/AddNewProductDialog/config'
import SimilarProductsAlert from '@/components/AddNewProductDialog/SimilarProductsAlert'

export default {
  name: 'AddNewProductDialog',
  components: {
    SimilarProductsAlert,
    Dialog,
    Form,
  },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      addingProduct: false,
      hasSimilarProducts: true,
    }
  },
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
    }),
    ...mapState('products', { products: state => state.data.products }),
    ...mapState({
      newProductDialog(state) {
        return state[getViewStore(this.$route.name)].newProductDialog
      },
      filters(state) {
        return state[getViewStore(this.$route.name)].filters
      },
    }),
    ...mapState('salesView', ['currentSale']),
    ...mapState('purchasesView', {
      selectedPurchase: state => state.selectedPurchase,
      fromReturnProductDialog: state =>
        state.newProductDialog.fromReturnProductDialog,
      barcodePurchase: state => state.newProductDialog.barcode,
    }),
    dialogConfig() {
      return setConfig(
        {
          dialog: {
            isOpen: this.newProductDialog.isOpen,
            isAcceptButtonDisabled: this.$v.inputs.$invalid,
            routeName: this.$route.name,
          },
          inputs: this.inputs,
          v: this.$v.inputs,
          currentView: this.$route.name,
          showByWeight:
            'showByWeight' in this.newProductDialog
              ? this.newProductDialog.showByWeight
              : true,
          hasSimilarProducts: this.hasSimilarProducts,
        },
        {
          dialog: {
            closeDialog: this.onCloseDialog,
            acceptDialog: this.onSubmitDialog,
            track: this.$track,
          },
          seCurrentViewGroup: this.seCurrentViewGroup,
        }
      )
    },
    validCodeText() {
      return `(${
        upcTools.isSupportedUpcOrEan(this.$barcodeScanner.getPreviousCode())
          ? this.getTranslatedText('productsView.similarProducts.validCode')
          : this.getTranslatedText('productsView.similarProducts.invalidCode')
      })`
    },
  },
  searchInput: null,
  methods: {
    getTranslatedText,
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('products', [
      productsActions.addNewProduct,
      productsActions.setProductsOrSuperCategoriesFetching,
    ]),
    ...mapActions('productsView', {
      toggleAddProductDialogFromProductsView:
        productsViewActions.toggleAddProductDialog,
      setSearchTermFromProductsView: productsViewActions.setSearchTermFilter,
      toggleDetailDialog: productsViewActions.toggleDetailDialog,
      setProductsGroup: productsViewActions.setGroupFilter,
      setSelectedProduct: productsViewActions.setSelectedProduct,
    }),
    ...mapActions('salesView', {
      toggleAddProductDialogFromSalesView:
        salesViewActions.toggleAddProductDialog,
      setSearchTermFromSalesView: salesViewActions.setSearchTermFilter,
      setSalesGroup: salesViewActions.setGroupFilter,
    }),
    ...mapActions('purchasesView', [
      purchasesViewActions.setHiddenReturnProductDialog,
    ]),
    ...mapActions('purchasesView', {
      setAddProductDialogStatusFromPurchasesView:
        purchasesViewActions.setAddProductDialogStatus,
      setPurchasesGroup: purchasesViewActions.setGroupFilter,
      setSearchTermFromPurchasesView: purchasesViewActions.setSearchTermFilter,
    }),
    ...mapActions('customPromotionsView', {
      toggleAddProductDialogFromPromotionsView:
        customPromotionsViewActions.toggleAddProductDialog,
    }),
    setProperties: function() {
      this.dialogConfig.fields.forEach(field => {
        !isNil(field.defaultValue)
          ? this.$set(this.inputs, field.id, field.defaultValue)
          : this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    setCurrentViewGroup(value) {
      switch (getViewStore(this.$route.name)) {
        case 'productsView':
          this.setProductsGroup(value)
          break
        case 'purchasesView':
          this.setPurchasesGroup(value)
          break
        case 'salesView':
          this.setSalesGroup(value)
          break
      }
    },

    closeDialog() {
      switch (getViewStore(this.$route.name)) {
        case 'productsView':
          this.toggleAddProductDialogFromProductsView()
          break
        case 'purchasesView':
          if (this.fromReturnProductDialog) {
            this[purchasesViewActions.setHiddenReturnProductDialog](false)
          }
          this.setAddProductDialogStatusFromPurchasesView({
            isOpen: false,
            barcode: null,
          })
          break
        case 'salesView':
          this.toggleAddProductDialogFromSalesView()
          break
        case 'customPromotionsView':
          this.toggleAddProductDialogFromPromotionsView()
          break
      }
    },
    setCurrentViewSearchTerm(value) {
      switch (getViewStore(this.$route.name)) {
        case 'productsView':
          this.setSearchTermFromProductsView(value)
          break
        case 'purchasesView':
          this.setSearchTermFromPurchasesView(value)
          break
        case 'salesView':
          this.setSearchTermFromSalesView(value)
          break
      }
    },
    getIdbyOperationType() {
      let id = null
      switch (getViewStore(this.$route.name)) {
        case 'purchasesView':
          id = this.selectedPurchase._id
          break
        case 'salesView':
          id = this.currentSale.saleIndex
          break
        case 'productsView':
          break
      }
      return id
    },
    onCloseDialog() {
      Object.keys(this.inputs).forEach(key => {
        if (key in this.$v.inputs) this.$v.inputs[key].$reset()
      })
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[productsActions.setProductsOrSuperCategoriesFetching](false)
      this.closeDialog()
      this.setCurrentViewSearchTerm(null)
      this.$root.$emit('reset')
      this.setCurrentViewGroup(this.defaultProductsFilter)
    },
    async onSubmitDialog() {
      if (this.addingProduct === true) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'AddNewProductDialog',
        name: `Save new product`,
      })
      this.addingProduct = true
      const newProduct = getObjectCopy(this.inputs)
      newProduct.upc = this.fromReturnProductDialog
        ? this.barcodePurchase
        : this.filters.searchTerm
      newProduct.categoryId = -1
      newProduct.price = formatNumberToDb(newProduct.price)
      newProduct.cost = formatNumberToDb(0)
      this[productsActions.setProductsOrSuperCategoriesFetching](true)
      rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
        event: ADD_PRODUCT_EVENTS.events.addNewProduct.name,
        data: {
          items: [newProduct],
          fromReturnProductDialog: this.fromReturnProductDialog,
        },
      })
    },
    addProductListener(event, payload) {
      const events = ADD_PRODUCT_EVENTS.events
      const replies = {
        [events.addNewProduct.replies.success]: () =>
          this.onProductAdded(payload.data),
        [events.addNewProduct.replies.error]: () =>
          this.onAddingProductError(payload.data),
      }
      if (payload.event in replies) replies[payload.event]()
    },
    async onProductAdded(data) {
      const { newProduct } = data
      await this[productsActions.addNewProduct]({
        newProduct,
        currentView: getViewStore(this.$route.name),
        index: this.getIdbyOperationType(),
        fromReturnProductDialog: this.fromReturnProductDialog,
      })
      if (this.fromReturnProductDialog) {
        this.$root.$emit('new-product-from-return-product-dialog', {
          newProduct,
        })
      }
      notificationsService.showInfo(
        'productsView.listView.messages.newProductAdded',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
      this.addingProduct = false
      this.$root.$emit('newProductWasAdded', newProduct)
      this.onCloseDialog()
    },
    onAddingProductError(data) {
      this.setSelectedProduct(null)
      this.toggleDetailDialog()
      this[productsActions.setProductsOrSuperCategoriesFetching](false)
      notificationsService.showError(data.errorMsg, this.$vuetify.lang, {
        timeout: 8000,
      })
      this.addingProduct = false
      this.onCloseDialog()
    },
  },
  validations() {
    return this.validators
  },
  created() {
    this.setProperties()
    if (testMode) return
    rendererEventsService.subscribe(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductListener
    )
  },
  mounted() {
    this.$barcodeScanner.destroy()
  },
  beforeDestroy() {
    this.$loading.hide()
    this.$root.$emit('enable-scanner', {})
    rendererEventsService.removeListener(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductListener
    )
  },
}
</script>

<style scoped lang="scss">
.barcode-scanned {
  background: var(--v-cardBackgroundSecondary-base);
  padding: 4px 12px;
  border-radius: 10px;
}
</style>
